options.styles:
.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
  height: 100%;
  padding: 12px 24px;
  background: linear-gradient(135deg, #0F172A 0%, #1E293B 100%);
  border: 1px solid #334155;
  border-left: 6px solid #EA580C;
  border-radius: 8px;
  font-family: Inter, Roboto, sans-serif;
  color: #F8FAFC;
}
.hero-left { display: flex; align-items: center; gap: 16px; }
.logo-badge {
  background: #EA580C;
  color: #FFFFFF;
  font-weight: 900;
  font-size: 13px;
  letter-spacing: 0.1em;
  padding: 8px 14px;
  border-radius: 6px;
  box-shadow: 0 2px 10px rgba(234, 88, 12, 0.4);
}
.hero-titles h1 { margin: 0; font-size: 20px; font-weight: 800; color: #FFFFFF; letter-spacing: -0.01em; }
.hero-titles p { margin: 3px 0 0; font-size: 12px; color: #94A3B8; }
.hero-right { display: flex; align-items: center; gap: 10px; }
.chip {
  display: flex;
  flex-direction: column;
  background: rgba(15, 23, 42, 0.7);
  border: 1px solid #334155;
  border-radius: 6px;
  padding: 6px 12px;
}
.chip-lbl { font-size: 9px; font-weight: 800; color: #94A3B8; text-transform: uppercase; letter-spacing: 0.05em; }
.chip-val { font-size: 12px; font-weight: 800; color: #FFFFFF; margin-top: 1px; }
.badge {
  padding: 8px 16px;
  border-radius: 20px;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: 0.04em;
}
.badge.ok { background: rgba(34, 197, 94, 0.2); color: #22C55E; border: 1px solid #22C55E; }
.badge.bad { background: rgba(239, 68, 68, 0.2); color: #EF4444; border: 1px solid #EF4444; }
